-- Karnataka district election offices publish these constituency-specific lists.
-- The dated PDF remains available for scanned reports while venue transcription
-- is reviewed. Only complete, sequential tables supply individual venue records.
-- The polling-area column and any household ranges are excluded.
BEGIN;

LOCK TABLE public.dataset_versions, public.polling_booths IN SHARE ROW EXCLUSIVE MODE;

DO $check$
BEGIN
  IF (SELECT count(*) FROM public.constituencies
      WHERE state_code = 'KA' AND ac_no IN (69,70,71,72,73,74,75,178,179,180,181)
        AND primary_dataset_version_id = 'eci_karnataka_schedule_xiv_2026_11_27') <> 11
  THEN
    RAISE EXCEPTION 'Verify the Karnataka constituency crosswalk before importing polling stations';
  END IF;
END $check$;

