  (181, 271, 'Motagondanahalli-2', 'Govt Higher Primary School Room No-2 Motagondanahalli -2', 'eci_polling_stations_ka_ac_181_20241029'),
  (181, 272, 'Pemmanahalli', 'Govt Lower Primary School Pemmanahallii', 'eci_polling_stations_ka_ac_181_20241029'),
  (181, 273, 'Dasegowdanapalya', 'Govt Lower Primary School Dasegowdanapalya', 'eci_polling_stations_ka_ac_181_20241029'),
  (181, 274, 'Mallur', 'Govt Higher Primary School Mallur', 'eci_polling_stations_ka_ac_181_20241029'),
  (181, 275, 'Bantarakuppe', 'Govt Higher Primary School Bantarakuppe', 'eci_polling_stations_ka_ac_181_20241029'),
  (181, 276, 'Mummenahalli', 'Govt Lower Primary School Mummenahalli', 'eci_polling_stations_ka_ac_181_20241029'),
  (181, 277, 'Avalakuppe', 'Govt Higher Primary School Avalakuppe', 'eci_polling_stations_ka_ac_181_20241029'),
  (181, 278, 'Soladevanahalli', 'Govt Higher Primary School Soladevanahalli', 'eci_polling_stations_ka_ac_181_20241029')
)
INSERT INTO public.polling_booths
  (id, internal_id, state_code, constituency_id, constituency_internal_id, booth_number,
   booth_name, polling_station_name, polling_station_address, primary_dataset_version_id, data_status)
SELECT c.id || '-B' || lpad(b.booth_number::text, 3, '0'), gen_random_uuid(),
       c.state_code, c.id, c.internal_id, b.booth_number,
       b.venue, b.venue, b.locality, b.version_id, 'OFFICIAL'
FROM published_booths b
JOIN public.constituencies c ON c.state_code = 'KA' AND c.ac_no = b.ac_no
ON CONFLICT (constituency_id, booth_number) DO NOTHING;

DO $check$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM (VALUES (178, 293), (179, 294), (181, 278)) AS expected(ac_no, stations)
    JOIN public.constituencies c ON c.state_code = 'KA' AND c.ac_no = expected.ac_no
    LEFT JOIN public.polling_booths b ON b.constituency_id = c.id
      AND b.primary_dataset_version_id = 'eci_polling_stations_ka_ac_' || expected.ac_no || '_20241029'
      AND b.data_status = 'OFFICIAL'
    GROUP BY expected.ac_no, expected.stations
    HAVING count(b.id) <> expected.stations OR min(b.booth_number) <> 1
       OR max(b.booth_number) <> expected.stations
  ) THEN
    RAISE EXCEPTION 'Karnataka retains an incomplete or conflicting polling-station list';
  END IF;
END $check$;

COMMIT;
